#!/usr/bin/env node
/**
 * 「手写文件清单」门禁。
 *
 * 生成器产出的一律带 `// Auto-generated by Codegen Engine` 标记；手写的没有。
 * 把当前无标记的文件钉成基线，之后:
 *   * 新增手写文件 -> 提示收紧基线（人确认后 `--update-baseline`）
 *   * **基线里的文件变成"有标记"** -> 说明它被批量重生成**覆盖**了 -> **失败**
 *     （这正是 `member-user.repository.ts` 被覆盖两次的那种事故）
 *
 * 用法:
 *   node scripts/check-handwritten-files.cjs                  # 门禁
 *   node scripts/check-handwritten-files.cjs --audit          # 只看清单
 *   node scripts/check-handwritten-files.cjs --update-baseline
 */
const fs = require("node:fs")
const path = require("node:path")
const { isGeneratedFile } = require("./lib/generated-file.cjs")

const ROOT = path.resolve(__dirname, "..")
const BASELINE = path.join(ROOT, "docs", "architecture", "artifacts", "handwritten-files-baseline.json")
const auditOnly = process.argv.includes("--audit")
const updateBaseline = process.argv.includes("--update-baseline")

/** 生成器会写这些目录 —— 里面的无标记文件就是"手写插进来的"。 */
const SCAN_DIRS = ["backend/repositories", "backend/services", "backend/validators", "frontend/pages", "frontend/components"]

function collect() {
  const handwritten = []
  const roots = [path.join(ROOT, "packages/plugins"), path.join(ROOT, "packages/domains")]
  for (const root of roots) {
    if (!fs.existsSync(root)) continue
    for (const domain of fs.readdirSync(root)) {
      for (const dir of SCAN_DIRS) {
        const full = path.join(root, domain, dir)
        if (!fs.existsSync(full)) continue
        for (const file of fs.readdirSync(full)) {
          if (!/\.(ts|tsx)$/.test(file)) continue
          if (file.includes("__tests__")) continue
          const rel = path.relative(ROOT, path.join(full, file)).replace(/\\/g, "/")
          if (!isGeneratedFile(path.join(full, file))) handwritten.push(rel)
        }
      }
    }
  }
  return handwritten.sort()
}

function main() {
  const handwritten = collect()
  console.log(`[handwritten] 扫描 ${SCAN_DIRS.length} 类目录，手写文件 ${handwritten.length} 个`)

  if (auditOnly) {
    for (const rel of handwritten.slice(0, 25)) console.log(`  · ${rel}`)
    if (handwritten.length > 25) console.log(`  … 其余 ${handwritten.length - 25} 个`)
    return
  }

  if (updateBaseline) {
    fs.mkdirSync(path.dirname(BASELINE), { recursive: true })
    fs.writeFileSync(BASELINE, JSON.stringify({ note: "生成器目录下的手写文件清单（基线）", handwritten }, null, 2) + "\n")
    console.log(`  已写入基线（${handwritten.length} 个）`)
    return
  }

  const baseline = fs.existsSync(BASELINE) ? JSON.parse(fs.readFileSync(BASELINE, "utf8")).handwritten ?? [] : []
  const current = new Set(handwritten)
  const baselineSet = new Set(baseline)

  // ★ 最要命的一种: 基线里的手写文件现在带上了生成标记 —— 说明它被覆盖了
  const clobbered = baseline.filter((rel) => !current.has(rel) && isGeneratedFile(path.join(ROOT, rel)))
  const added = handwritten.filter((rel) => !baselineSet.has(rel))

  if (clobbered.length > 0) {
    console.error(`\n[handwritten] FAIL: ${clobbered.length} 个手写文件**被生成器覆盖**了`)
    for (const rel of clobbered.slice(0, 10)) console.error(`  ✗ ${rel}`)
    console.error("\n修复: 从 git 恢复该文件；并让重生成工具排除它（见 scripts/lib/generated-file.cjs）。")
    process.exit(1)
  }
  if (added.length > 0) {
    console.log(`[handwritten] 新增手写文件 ${added.length} 个（确认后跑 --update-baseline 收紧）`)
    for (const rel of added.slice(0, 10)) console.log(`  + ${rel}`)
  }
  console.log(`[handwritten] PASS（基线 ${baseline.length} 个，被覆盖 0 个）`)
}

main()
